---RefreshUI
---@param funcSwitchId number 功能切割表id
function CommonLackMaterialItemEntranceNode:RefreshUI(funcSwitchId, goodsVo, index, gainNum)
    self.gainNum = gainNum
    ---是否配置功能
    local isConfFunc = funcSwitchId ~= nil
    KTool.SetActive(self.ImgNon.gameObject, not isConfFunc)
    KTool.SetActive(self.ImgIcon.gameObject, isConfFunc)
    local bgStatus = 2
    local isUnlock = false
    if isConfFunc then
        SetButtonAction(self.controller.gameObject, Bind(self, self.OnClickNodeAction))

        ---@type TableML.TableFileRow
        local row = goodsConfMgr:GetJumpModuleRow(funcSwitchId)
        local functionName = GoodsUtils.GetFunctionName(row, goodsVo, index)
        self.TxtName.textComp.text = functionName

        local systemToggleId = row:Get("functionID")
        self.ImgIconAlterable:LoadSprite(ParseUtils.ParsePathName(row, "systemIcon"))

        isUnlock = GameUtils.IsUnlockedBySystemTogId(systemToggleId)
        local status = isUnlock and 1 or 2
        self.TxtName.Status = status
        self.ImgIcon.Status = status
        
        bgStatus = isUnlock and 1 or bgStatus
        self.row = row
        self.goodsVo = goodsVo
        self.index = index
    end
    KTool.SetActive(self.ImgLock.gameObject, not isUnlock)

    self.ImgBg.Status = bgStatus

end

