function CommonLackMaterialItemEntranceNode:OnClickNodeAction()
    blocker:AddCondition("CommonLackMaterialItemEntranceNode")
    cs_coroutine.start(function()
        blocker:RemoveCondition("CommonLackMaterialItemEntranceNode")
        cs_coroutine.yield_return(UIModule.BackDialog())

        local moduleId = checkInt(self.row:GetPrimaryKey())
        if moduleId == 401 then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICompositeEntryDialog, parameters = {gainId = self.goodsVo.id, gainNum = self.gainNum} })
        else
            goodsConfMgr:ExecuteJump(self.row, self.goodsVo, self.index)

        end

    end)


end

---------------------------------------------------
--- click handler end --
---------------------------------------------------

return CommonLackMaterialItemEntranceNode